//! Original bounded implicit graph, min/max and polynomial smooth CSG.
use serde::{Serialize,Deserialize};
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(tag="kind",rename_all="snake_case",deny_unknown_fields)]pub enum Field{Sphere{center:[f64;3],radius:f64},Box{center:[f64;3],half_size:[f64;3]},Plane{normal:[f64;3],offset:f64},Union{a:usize,b:usize},Intersect{a:usize,b:usize},Subtract{a:usize,b:usize},SmoothUnion{a:usize,b:usize,k:f64},SmoothIntersect{a:usize,b:usize,k:f64},SmoothSubtract{a:usize,b:usize,k:f64}}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Graph{pub nodes:Vec<Field>,pub output:usize}
fn finite(x:f64)->bool{x.is_finite()&&x.abs()<=1e6}
impl Graph{
 pub fn validate(&self)->Result<(),String>{if self.nodes.is_empty()||self.nodes.len()>128||self.output>=self.nodes.len(){return Err("SDF graph1..128 nodes and valid output required".into());}for(i,n)in self.nodes.iter().enumerate(){match n{Field::Sphere{center,radius}=>{if center.iter().any(|v|!finite(*v))||!finite(*radius)||*radius<=0.{return Err("finite sphere positive radius".into());}},Field::Box{center,half_size}=>{if center.iter().any(|v|!finite(*v))||half_size.iter().any(|v|!finite(*v)||*v<=0.){return Err("finite box positive half sizes".into());}},Field::Plane{normal,offset}=>{if !finite(*offset)||normal.iter().any(|v|!finite(*v)){return Err("bounded plane".into());}super::vertex_stream::unit(*normal)?;},Field::Union{a,b}|Field::Intersect{a,b}|Field::Subtract{a,b}=>{if *a>=i||*b>=i{return Err("CSG inputs must reference earlier nodes".into());}},Field::SmoothUnion{a,b,k}|Field::SmoothIntersect{a,b,k}|Field::SmoothSubtract{a,b,k}=>{if *a>=i||*b>=i||!finite(*k)||*k<=0.{return Err("smooth CSG earlier inputs and k>0 required".into());}}}}Ok(())}
 pub fn sample(&self,p:[f64;3])->Result<f64,String>{self.validate()?;self.evaluate(p)}
 pub(crate) fn evaluate(&self,p:[f64;3])->Result<f64,String>{if p.iter().any(|v|!finite(*v)){return Err("SDF point abs<=1e6 finite required".into());}let mut v=Vec::with_capacity(self.nodes.len());let min_smooth=|a:f64,b:f64,k:f64|{let h=(0.5+0.5*(b-a)/k).clamp(0.,1.);b*(1.-h)+a*h-k*h*(1.-h)};for n in &self.nodes{let d=match n{Field::Sphere{center,radius}=>(p[0]-center[0]).hypot(p[1]-center[1]).hypot(p[2]-center[2])-radius,Field::Box{center,half_size}=>{let q:[f64;3]=std::array::from_fn(|j|(p[j]-center[j]).abs()-half_size[j]);q[0].max(0.).hypot(q[1].max(0.)).hypot(q[2].max(0.))+q[0].max(q[1]).max(q[2]).min(0.)},Field::Plane{normal,offset}=>{let n=super::vertex_stream::unit(*normal)?;n.iter().zip(p).map(|(a,b)|a*b).sum::<f64>()-offset},Field::Union{a,b}=>f64::min(v[*a],v[*b]),Field::Intersect{a,b}=>f64::max(v[*a],v[*b]),Field::Subtract{a,b}=>f64::max(v[*a],-v[*b]),Field::SmoothUnion{a,b,k}=>min_smooth(v[*a],v[*b],*k),Field::SmoothIntersect{a,b,k}=>-min_smooth(-v[*a],-v[*b],*k),Field::SmoothSubtract{a,b,k}=>-min_smooth(-v[*a],v[*b],*k)};v.push(d);}Ok(v[self.output])}
 #[cfg(feature="surface-contour")]pub(crate) fn normal(&self,p:[f64;3],eps:f64)->Result<[f64;3],String>{let mut n=[0.;3];for j in 0..3{let mut a=p;let mut b=p;a[j]+=eps;b[j]-=eps;n[j]=self.evaluate(a)?-self.evaluate(b)?;}super::vertex_stream::unit(n)}
}
#[cfg(test)]mod tests{use super::*;#[test]fn analytic_and_smooth_signs(){let mut g=Graph{nodes:vec![Field::Sphere{center:[0.;3],radius:1.},Field::Sphere{center:[1.,0.,0.],radius:1.},Field::SmoothUnion{a:0,b:1,k:0.2}],output:2};assert!(g.sample([0.5,0.,0.]).unwrap()<0.);g.nodes[2]=Field::SmoothIntersect{a:0,b:1,k:0.2};assert!(g.sample([0.5,0.,0.]).unwrap()<0.);g.nodes[2]=Field::SmoothSubtract{a:0,b:1,k:0.2};assert!(g.sample([0.9,0.,0.]).unwrap()>0.);g.nodes[2]=Field::Union{a:2,b:1};assert!(g.validate().is_err());}}
